1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const isWithinOneStep = (coordinate: number, other: number): boolean =>
7	  Math.abs(coordinate - other) <= 1;
8	
9	const isNeighbor = (cell: Cell, other: Cell): boolean => {
10	  const [x, y] = cell;
11	  const [otherX, otherY] = other;
12	  return (
13	    isWithinOneStep(x, otherX) &&
14	    isWithinOneStep(y, otherY) &&
15	    !isSameCell(cell, other)
16	  );
17	};
18	
19	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
20	  liveCells.filter((other) => isNeighbor(cell, other)).length;
21	
22	const neighborsOf = ([x, y]: Cell): Cell[] =>
23	  [-1, 0, 1].flatMap((dx) =>
24	    [-1, 0, 1]
25	      .filter((dy) => !(dx === 0 && dy === 0))
26	      .map((dy): Cell => [x + dx, y + dy]),
27	  );
28	
29	const isAlive = (cell: Cell, liveCells: Cell[]): boolean =>
30	  liveCells.some((other) => isSameCell(cell, other));
31	
32	const survives = (cell: Cell, liveCells: Cell[]): boolean => {
33	  const neighborCount = countLiveNeighbors(cell, liveCells);
34	  return neighborCount === 2 || neighborCount === 3;
35	};
36	
37	const isBorn = (cell: Cell, liveCells: Cell[]): boolean =>
38	  !isAlive(cell, liveCells) && countLiveNeighbors(cell, liveCells) === 3;
39	
40	export function nextGeneration(liveCells: Cell[]): Cell[] {
41	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
42	  const births = liveCells
43	    .flatMap(neighborsOf)
44	    .filter(
45	      (candidate, index, candidates) =>
46	        candidates.findIndex((other) => isSameCell(candidate, other)) ===
47	          index && isBorn(candidate, liveCells),
48	    );
49	  return [...survivors, ...births];
50	}
